"use client";
import Link from "next/link";
import { useActionState, useState } from "react";
import { useFormStatus } from "react-dom";
import Card from "../components/ui/Card";
import {
  formatPeptideExecutionSummary,
  resolvePeptideDose,
} from "../domain/services/ExecutionPhaseResolver";

const DAYS=[["sunday","Sun"],["monday","Mon"],["tuesday","Tue"],["wednesday","Wed"],["thursday","Thu"],["friday","Fri"],["saturday","Sat"]];
export function PeptideExecutionDetailScreen({item,protocol,localDate,supportTerminology=false}){const dose=resolvePeptideDose(item,localDate);const configured=Boolean(item?.timeline?.length);const status=item?.active===false?"Inactive":dose.current?"Current":dose.next?"Starts later":"Needs dosing update";return <Shell><Header protocol={protocol} supportTerminology={supportTerminology}/>{!configured?<Card><b>Not configured</b><p className="mt-1 text-sm text-[var(--text-secondary)]">Add a dosing strategy to complete this Support plan.</p></Card>:<div className="space-y-3"><Row label="Current dose" value={dose.current?`${dose.current.dose.amount} ${dose.current.dose.unit}`:"No active phase"}/><Row label="Current phase" value={dose.current?`${dose.current.startDate} – ${dose.current.endDate??"Until changed"}`:"Not active"}/><Row label="Schedule" value={formatPeptideExecutionSummary(item,localDate)}/><Row label="Next dose change" value={dose.next?`${dose.next.startDate} · ${dose.next.dose.amount} ${dose.next.dose.unit}`:"None scheduled"}/><Row label="Status" value={status}/></div>}<Link className="flex min-h-12 items-center justify-center rounded-2xl bg-[var(--primary)] font-extrabold text-white" href={`/profile/operating-plan/execution/peptides/${protocol.id}?edit=1`}>{supportTerminology?(item?"Edit Support":"Configure Support"):(item?"Edit Execution":"Configure Execution")}</Link></Shell>}

export function PeptideExecutionEditorScreen({action,item,protocol}){const[state,formAction]=useActionState(action,{message:null,values:null});const value=state.values??item;const[cadence,setCadence]=useState(value.cadence?.type??"weekly");const[days,setDays]=useState(value.preferredSchedule?.daysOfWeek??[]);const initialTime=/^\d{2}:\d{2}$/.test(value.preferredSchedule?.timeOfDay??"")?"specific":value.preferredSchedule?.timeOfDay??"before_bed";const[timing,setTiming]=useState(initialTime);const[phases,setPhases]=useState(()=>(value.timeline??[]).map((phase,index)=>({...phase,clientKey:`saved-${index}`})));const updatePhase=(index,patch)=>setPhases(phases.map((phase,phaseIndex)=>phaseIndex===index?{...phase,...patch}:phase));const timelineJson=JSON.stringify(phases.map(({clientKey:_,...phase})=>phase));return <main className="app-surface min-h-screen"><form action={formAction} className="mx-auto max-w-[393px] space-y-5 px-4 pb-28 pt-10"><Header protocol={protocol}/>{state.message&&<p className="rounded-xl bg-[var(--surface-muted)] p-3 text-sm font-semibold">{state.message}</p>}<Section title="Recurring schedule"><Select label="Frequency" name="cadence" value={cadence} onChange={(e)=>setCadence(e.target.value)} options={[["weekly","Weekly"],["specific_days","Specific days"]]}/><div><Label>Selected days</Label><div className="flex flex-wrap gap-2">{DAYS.map(([id,label])=><button aria-pressed={days.includes(id)} className={`min-h-11 rounded-full border px-3 text-xs font-extrabold ${days.includes(id)?"border-[var(--primary)] text-[var(--primary)]":"border-[var(--divider)]"}`} key={id} onClick={()=>setDays(cadence==="weekly"?[id]:days.includes(id)?days.filter((d)=>d!==id):[...days,id])} type="button">{label}</button>)}</div><input name="days" type="hidden" value={days.join(",")}/></div><Select label="Preferred time" name="timing" value={timing} onChange={(e)=>setTiming(e.target.value)} options={[["morning","Morning"],["evening","Evening"],["before_bed","Night"],["specific","Specific time"]]}/>{timing==="specific"&&<Field label="Specific local time" name="specificTime" type="time" defaultValue={/^\d{2}:\d{2}$/.test(value.preferredSchedule?.timeOfDay??"")?value.preferredSchedule.timeOfDay:""}/>}<div className="grid grid-cols-2 gap-3"><Field label="Start date" name="startDate" type="date" defaultValue={value.preferredSchedule?.startDate}/><Field label="End date (optional)" name="endDate" type="date" defaultValue={value.preferredSchedule?.endDate??""}/></div>{value.timingContext&&<input name="timingContext" type="hidden" value={value.timingContext}/>}</Section><Section title="Dosing timeline"><p className="text-xs font-semibold text-[var(--text-secondary)]">Phases remain chronological. Leave the final end date blank for Until changed.</p><input name="timelineOperation" type="hidden" value="replace"/><input name="timelineJson" type="hidden" value={timelineJson}/>{phases.map((phase,index)=><div className="space-y-3 rounded-xl border border-[var(--divider)] p-3" key={phase.clientKey}><div className="grid grid-cols-2 gap-3"><Field label="Start" type="date" value={phase.startDate} onChange={(e)=>updatePhase(index,{startDate:e.target.value})}/><Field label="End / Until changed" type="date" value={phase.endDate??""} onChange={(e)=>updatePhase(index,{endDate:e.target.value||null})}/><Field label="Dose" value={phase.dose?.amount??""} onChange={(e)=>updatePhase(index,{dose:{...phase.dose,amount:e.target.value}})}/><Field label="Unit" value={phase.dose?.unit??""} onChange={(e)=>updatePhase(index,{dose:{...phase.dose,unit:e.target.value}})}/></div><Field label="Phase note (optional)" value={phase.notes??""} onChange={(e)=>updatePhase(index,{notes:e.target.value})}/><button className="min-h-11 text-sm font-bold text-[var(--text-secondary)]" type="button" onClick={()=>setPhases(phases.filter((_,i)=>i!==index))}>Remove phase</button></div>)}<button className="min-h-11 rounded-xl border border-[var(--divider)] px-3 text-sm font-extrabold" type="button" onClick={()=>setPhases([...phases,{clientKey:`new-${Date.now()}-${phases.length}`,startDate:"",endDate:null,dose:{amount:"",unit:"mg"},notes:""}])}>Add phase</button></Section><Section title="Notifications and priority"><Select label="Notifications" name="reminderPreference" defaultValue={value.reminderPreference??"none"} options={[["remind","Remind me"],["none","Keep in plan without reminders"]]}/><Select label="Priority" name="priority" defaultValue={value.priority??"normal"} options={[["high","High"],["normal","Normal"],["low","Low"]]}/></Section><Section title="Execution notes"><textarea className="min-h-24 w-full rounded-xl border border-[var(--divider)] bg-[var(--surface-muted)] p-3" maxLength={1000} name="notes" defaultValue={value.notes}/></Section><Submit/></form></main>}
function Shell({children}){return <main className="app-surface min-h-screen"><div className="mx-auto max-w-[393px] space-y-5 px-4 pb-28 pt-10">{children}</div></main>}
function Header({protocol,supportTerminology=false}){return <><Link className="inline-flex min-h-11 items-center text-sm font-semibold text-[var(--text-secondary)]" href="/profile/operating-plan">← Operating Plan</Link><header><p className="text-xs font-extrabold uppercase tracking-widest text-[var(--primary)]">{supportTerminology?"Peptide Support":"Peptide Execution"}</p><h1 className="mt-2 text-3xl font-extrabold">{protocol.name}</h1><p className="mt-2 text-sm text-[var(--text-secondary)]">{supportTerminology?"Review the current schedule and dosing strategy.":"Manage schedule and dosing phases without changing the protocol strategy."}</p></header></>}
function Row({label,value}){return <Card><p className="text-xs font-extrabold uppercase tracking-wider text-[var(--text-muted)]">{label}</p><p className="mt-1 text-sm font-semibold">{value}</p></Card>}
function Section({title,children}){return <section className="space-y-3 rounded-2xl bg-[var(--surface-elevated)] p-4"><h2 className="font-extrabold">{title}</h2>{children}</section>}
function Label({children}){return <span className="mb-2 block text-xs font-bold text-[var(--text-secondary)]">{children}</span>}
function Field({label,...props}){return <label><Label>{label}</Label><input className="min-h-12 w-full rounded-xl border border-[var(--divider)] bg-[var(--surface-muted)] px-3" {...props}/></label>}
function Select({label,options,...props}){return <label><Label>{label}</Label><select className="min-h-12 w-full rounded-xl border border-[var(--divider)] bg-[var(--surface-muted)] px-3" {...props}>{options.map(([id,text])=><option key={id} value={id}>{text}</option>)}</select></label>}
function Submit(){const{pending}=useFormStatus();return <button disabled={pending} className="min-h-12 w-full rounded-2xl bg-[var(--primary)] font-extrabold text-white disabled:opacity-60" type="submit">{pending?"Saving…":"Save Execution"}</button>}
